-- Migration to import timesheets/time entries from TropiTrack v1 to v2
-- This script imports time entry data from the v1 structure
--
-- Data source: CSV export from Supabase AI query on v1 database
-- Total records: 2497 time entries

-- Import time entries
-- Note: Workers and projects must already be imported and matched by name
INSERT INTO public.time_entries (
    worker_id,
    project_id,
    company_id,
    date,
    start_time,
    end_time,
    break_duration_minutes,
    regular_hours,
    overtime_hours,
    notes,
    approved_by,
    approved_at,
    created_by,
    created_at,
    updated_at
)
SELECT
    -- Match worker by name (v1 name vs v2 first_name + last_name)
    w2.id as worker_id,
    -- Match project by name
    p2.id as project_id,
    -- Get company_id from worker (workers already have company_id set)
    w2.company_id as company_id,
    v1_entries.date,
    v1_entries.start_time,
    v1_entries.end_time,
    COALESCE(v1_entries.break_duration_minutes, 0) as break_duration_minutes,
    v1_entries.regular_hours,
    COALESCE(v1_entries.overtime_hours, 0) as overtime_hours,
    NULLIF(v1_entries.notes, '') as notes,
    -- approved_by is NULL for now (can be updated later if needed)
    NULL as approved_by,
    v1_entries.approved_at,
    -- created_by: Use the provided UUID if it exists in profiles, otherwise find a valid profile
    -- First try the provided UUID (if it exists in profiles), then try admin, then any profile
    COALESCE(
        (SELECT id FROM public.profiles WHERE id = v1_entries.created_by LIMIT 1),
        (SELECT id FROM public.profiles WHERE role = 'admin' LIMIT 1),
        (SELECT id FROM public.profiles LIMIT 1)
    ) as created_by,
    v1_entries.created_at,
    v1_entries.updated_at
FROM (
